6	 * Derives an owner's 'locality' (canonical region) from their city using a fixed
7	 * city-to-region table. Any city not in the table — including a null city — yields
8	 * "UNKNOWN".
9	 */
10	public final class Locality {
11	
12	    /** City -> canonical region. */
13	    private static final Map<String, String> CITY_REGION = Map.of(
14	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
15	
16	    private Locality() {
17	    }
18	
19	    /** Canonical region for {@code city}, or "UNKNOWN" when it is not in the table. */
20	    public static String of(String city) {
21	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
22	    }
23	}
